   }
   function scan(d){ var wh=0, pn=0, ps=0, k, px, py, r, g, b; for(py=0;py<320;py++) for(px=0;px<240;px++){ k=(py*240+px)*4; if(d[k+3]<200) continue; r=d[k]; g=d[k+1]; b=d[k+2];
